void sig_handler(int sig) {
    // SIGALRM processing logic
    printf("Alarm triggered.\n");
}

// 1. Set handler for SIGALRM
signal(SIGALRM, sig_handler);

// 2. Set alarm for 10 seconds
unsigned int time_remaining = alarm(10); // Returns 0

// 3. Reschedule/Cancel. Returns time left from previous alarm(10)
time_remaining = alarm(2);

// 4. Cancel pending alarm (time_remaining approx 2)
time_remaining = alarm(0);

pause(); // Wait for signal delivery
// SIGALRM handler must use reentrant functions.
// pause() blocks until signal delivery.
